const colors = {Python:'#3572a5',JavaScript:'#c7ad19',TypeScript:'#3178c6',HTML:'#e34c26',CSS:'#8c52ce',C:'#666','C++':'#f34b7d',Cython:'#d6b661',Ruby:'#a22',Other:'#aaa'};
