const dialog=$('#login-dialog');$('#login-button').addEventListener('click',()=>dialog.showModal());$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
// Render only our curated, source-reviewed projects. Never generate technical claims from an API description.
let projectData=null,refreshing=false;
const fmtDate = date => new Date(date).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});
function renderProjects(data){
 const list=$('#repo-list');list.replaceChildren();
 for(const p of data.projects){
  const row=document.createElement('article');row.className='repo-row';
  const top=document.createElement('div');top.className='repo-top';
  const a=document.createElement('a');a.className='repo-title';a.href=p.url;a.target='_blank';a.rel='noopener';const title=document.createElement('h3');title.className='repo-name';title.textContent=p.title;a.append(title);a.insertAdjacentHTML('beforeend',arrow);top.append(a);row.append(top);
  const date=document.createElement('p');date.className='project-date';date.textContent='Code updated '+fmtDate(p.pushed_at);row.append(date);
  if(p.status){const status=document.createElement('p');status.className='project-state';status.textContent=p.status;row.append(status);}
  const summary=document.createElement('p');summary.className='repo-description';summary.textContent=p.summary;row.append(summary);
  const ul=document.createElement('ul');ul.className='feats';for(const text of p.feats){const li=document.createElement('li');li.textContent=text;for(const term of ['12,000 canvas particles','Lazy-loaded project previews','UPC matching','80% catalog-match gate','Four opponents','real-time analysis heatmap']){const i=text.indexOf(term);if(i>=0){const strong=document.createElement('strong');strong.textContent=term;li.replaceChildren(document.createTextNode(text.slice(0,i)),strong,document.createTextNode(text.slice(i+term.length)));break;}}ul.append(li);}row.append(ul);
  const languages=Object.entries(p.languages||{}).sort((a,b)=>b[1]-a[1]);const total=languages.reduce((sum,[,n])=>sum+n,0);
  if(total){const bar=document.createElement('div');bar.className='language-bar';bar.setAttribute('aria-hidden','true');const legend=document.createElement('div');legend.className='language-legend';for(const [name,bytes] of languages){const pct=bytes/total*100;const color=colors[name]||'#999';const part=document.createElement('span');part.style.width=pct+'%';part.style.background=color;bar.append(part);const item=document.createElement('span');const dot=document.createElement('i');dot.style.background=color;item.append(dot,document.createTextNode(name+' '+(pct<.1?'<0.1':pct.toFixed(1))+'%'));legend.append(item);}row.append(bar,legend);if(p.language_note){const note=document.createElement('p');note.className='language-note';note.textContent=p.language_note;row.append(note);}}
  const details=document.createElement('details');details.className='project-source';const label=document.createElement('summary');label.textContent='Sources & measurement';const note=document.createElement('p');note.textContent='Languages are GitHub’s share of repository code bytes, not time spent or proficiency. '+(p.language_note||'');const source=document.createElement('a');source.href=p.evidence_url;source.target='_blank';source.rel='noopener';source.textContent='Technical details ↗';details.append(label,note,source);row.append(details);list.append(row);
 }
 $('#repo-status').textContent='GitHub snapshot · '+fmtDate(data.fetched_at)+'. Language percentages are based on code bytes.';
}
async function loadProjects(){try{const response=await fetch('./projects.json');if(!response.ok)throw Error();projectData=await response.json();renderProjects(projectData);}catch{$('#repo-status').textContent='Project data could not load. Use All repositories below, or refresh to try again.';}}
async function refreshProjects(){
 if(refreshing)return;refreshing=true;const button=$('#refresh-repos');button.disabled=true;$('#repo-status').textContent='Checking GitHub…';
 try{if(!projectData)await loadProjects();if(!projectData)throw Error();const projects=await Promise.all(projectData.projects.map(async p=>{const url='https://api.github.com/repos/frankstop/'+encodeURIComponent(p.name);const responses=await Promise.all([fetch(url,{signal:AbortSignal.timeout(12000)}),fetch(url+'/languages',{signal:AbortSignal.timeout(12000)})]);if(responses.some(r=>!r.ok))throw Error();const [meta,langs]=await Promise.all(responses.map(r=>r.json()));return {...p,pushed_at:meta.pushed_at,languages:langs};}));projectData={fetched_at:new Date().toISOString(),projects};renderProjects(projectData);$('#repo-status').textContent='Refreshed from GitHub just now. Language percentages are based on code bytes.';}catch{$('#repo-status').textContent=projectData?'Live refresh unavailable. Showing the saved GitHub snapshot from '+fmtDate(projectData.fetched_at)+'.':'GitHub is unavailable. Try again later.';}finally{refreshing=false;button.disabled=false;}
}
$('#refresh-repos').addEventListener('click',refreshProjects);loadProjects();
// A compact player: three real generative canvas experiments, no autoplay audio.
const canvas=$('#experiment'),ctx=canvas.getContext('2d'),player=$('#player');let w=0,h=0,mode='flow',running=!motion.matches,particles=[],ripples=[],tick=0,lastFrame=0;let center={x:.5,y:.5},pointerDown=false;
function seed(){particles=Array.from({length:700},()=>({x:Math.random()*w,y:Math.random()*h,angle:Math.random()*Math.PI*2,r:Math.random()*.47+.02,age:Math.random()*300,speed:Math.random()*.7+.3}));ripples=[{x:w*.5,y:h*.5,r:2,alpha:1}];tick=0;if(w&&h){ctx.fillStyle='#fbfbef';ctx.fillRect(0,0,w,h);for(let i=0;i<45;i++)draw(1);} }
function resize(){const b=canvas.getBoundingClientRect();if(!b.width||!b.height)return;w=b.width;h=b.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seed();}
function draw(dt){tick+=dt;ctx.fillStyle=mode==='flow'?'rgba(251,251,239,.12)':'rgba(251,251,239,.25)';ctx.fillRect(0,0,w,h);const cx=center.x*w,cy=center.y*h;
 if(mode==='flow'){ctx.lineWidth=.45;for(const p of particles){const dx=p.x-cx,dy=p.y-cy;const dist=Math.hypot(dx,dy);const angle=Math.atan2(dy,dx)+1.5+Math.sin(dist*.02+tick*.002)*.45;const px=p.x,py=p.y;p.x+=Math.cos(angle)*p.speed*dt*2;p.y+=Math.sin(angle)*p.speed*dt*2;p.age+=dt;if(p.x<0||p.x>w||p.y<0||p.y>h||dist<6||p.age>400){p.x=Math.random()*w;p.y=Math.random()*h;p.age=0;}else{ctx.strokeStyle='rgba(30,32,23,.42)';ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(p.x,p.y);ctx.stroke();}if(tick%10<1){ctx.fillStyle='#252820';ctx.fillRect(p.x,p.y,.9,.9);}}}
 else if(mode==='orbit'){for(let i=0;i<particles.length;i++){const p=particles[i];p.angle+=p.speed*.012*dt;const r=p.r*Math.min(w,h);const x=cx+Math.cos(p.angle)*r*1.7,y=cy+Math.sin(p.angle)*r;ctx.fillStyle=i%11===0?'#b0bf21':'#252820';ctx.beginPath();ctx.arc(x,y,i%11===0?1.9:.7,0,Math.PI*2);ctx.fill();}}
 else{if(tick%70<dt)ripples.push({x:Math.random()*w,y:Math.random()*h,r:1,alpha:.65});for(const r of ripples){r.r+=dt*.9;r.alpha-=dt*.003;ctx.strokeStyle='rgba(35,58,45,'+Math.max(r.alpha,0)+')';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(r.x,r.y,r.r*1.5,r.r,0,0,Math.PI*2);ctx.stroke();}ripples=ripples.filter(r=>r.alpha>0);}
}
function loop(time){const dt=Math.min((time-lastFrame)/16.67,2)||1;lastFrame=time;if(running&&!document.hidden&&visible)draw(dt);requestAnimationFrame(loop);}let visible=true;const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;});observer.observe(canvas);new ResizeObserver(resize).observe(canvas);requestAnimationFrame(loop);
function updatePlay(){const b=$('#play-button');b.setAttribute('aria-label',running?'Pause experiment':'Play experiment');$('#play-icon').innerHTML=running?'<path d="M9 5v14M15 5v14"/>':'<path d="m8 4 12 8-12 8Z" fill="currentColor" stroke="none"/>';}
$('#play-button').addEventListener('click',()=>{running=!running;updatePlay();});updatePlay();$('#reset-button').addEventListener('click',seed);
$('#experiment-select').addEventListener('change',e=>{mode=e.target.value;center={x:.5,y:.5};seed();const name={flow:'flow field',orbit:'particle orbit',ripple:'ripple pond'}[mode];canvas.setAttribute('aria-label','Interactive '+name+'. Drag, tap, or use arrow keys to move the center.');$('#experiment-help').textContent=mode==='ripple'?'Tap to make a ripple. Arrow keys move the center.':'Drag or tap to stir things up. Arrow keys work too.';});
function move(e){const b=canvas.getBoundingClientRect();center={x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))};if(mode==='ripple')ripples.push({x:center.x*w,y:center.y*h,r:1,alpha:1});if(!running)draw(1);}
canvas.addEventListener('pointerdown',e=>{pointerDown=true;canvas.setPointerCapture(e.pointerId);move(e);});canvas.addEventListener('pointermove',e=>{if(pointerDown)move(e);});canvas.addEventListener('pointerup',()=>{pointerDown=false;});canvas.addEventListener('pointercancel',()=>{pointerDown=false;});canvas.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();running=!running;updatePlay();return;}const dirs={ArrowLeft:[-.05,0],ArrowRight:[.05,0],ArrowUp:[0,-.05],ArrowDown:[0,.05]};if(dirs[e.key]){e.preventDefault();center.x=Math.max(0,Math.min(1,center.x+dirs[e.key][0]));center.y=Math.max(0,Math.min(1,center.y+dirs[e.key][1]));if(mode==='ripple')ripples.push({x:center.x*w,y:center.y*h,r:1,alpha:1});if(!running)draw(1);}});
let previousFocus=null;function setExpanded(on){if(on)previousFocus=document.activeElement;player.classList.toggle('expanded',on);document.body.style.overflow=on?'hidden':'';const b=$('#fullscreen-button');b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',on?'Close expanded mini player':'Expand mini player');if(on)canvas.focus();else previousFocus?.focus();}$('#fullscreen-button').addEventListener('click',()=>setExpanded(!player.classList.contains('expanded')));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!menu.hidden){closeMenu();menuButton.focus();}if(player.classList.contains('expanded'))setExpanded(false);}if(e.key==='Tab'&&player.classList.contains('expanded')){const items=Array.from(player.querySelectorAll('canvas,button,select'));const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
motion.addEventListener('change',e=>{if(e.matches){running=false;updatePlay();}});
const thoughts=['Have a little fun with it.','Moo-ve fast. Test things.','Good code. Better snacks.','One more tiny experiment.'];let thought=0;$('#cow-button').addEventListener('click',()=>{$('#cow-message').textContent=thoughts[++thought%thoughts.length];});
// Local device time is the only clock source; hands include seconds and milliseconds.
for(let i=0;i<60;i++){const t=document.createElement('i');t.className='tick'+(i%5===0?' major':'');t.style.setProperty('--a',i*6+'deg');$('#ticks').append(t);}for(let i=1;i<=12;i++){const angle=(i*30-90)*Math.PI/180;const n=document.createElement('span');n.className='numeral';n.textContent=i;n.style.left=(50+Math.cos(angle)*36)+'%';n.style.top=(50+Math.sin(angle)*36)+'%';$('#numerals').append(n);}
let lastSecond=-1;function updateClock(){const now=new Date(),seconds=now.getSeconds()+now.getMilliseconds()/1000,minutes=now.getMinutes()+seconds/60,hours=now.getHours()%12+minutes/60;$('#hour-hand').style.transform='rotate('+hours*30+'deg)';$('#minute-hand').style.transform='rotate('+minutes*6+'deg)';$('#second-hand').style.transform='rotate('+seconds*6+'deg)';if(now.getSeconds()!==lastSecond){lastSecond=now.getSeconds();const label=now.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',second:'2-digit'});$('#digital-time').textContent=label;$('#digital-time').dateTime=now.toISOString();$('.clock').setAttribute('aria-label','Local time '+label);$('#clock-date').textContent=now.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});$('#timezone').textContent=Intl.DateTimeFormat().resolvedOptions().timeZone.replaceAll('_',' ');} }updateClock();setInterval(updateClock,motion.matches?1000:50);
